import{creatureBuilder}from'./dungeon-creature-mesh.js';
export const ROOT_SECTION=Object.freeze([[-.7,-1],[.7,-1],[1,-.7],[1,.7],[.7,1],[-.7,1],[-1,.7],[-1,-.7]].map(Object.freeze));
export const WOOD=['#ed9353','#9c3824','#591d35'];
const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],unit=a=>{const d=Math.hypot(...a)||1;return a.map(n=>n/d);};
export const rootProject=([x,y,z])=>({x:x+y/11,y:y*8/11-z});
export function tubeMesh(id,points,radius=3,ramp=WOOD){const m=creatureBuilder({soft:true}),rings=points.map((p,i)=>{const rr=typeof radius==='function'?radius(i/(points.length-1)):radius,a=points[Math.max(0,i-1)],b=points[Math.min(points.length-1,i+1)],t=unit(b.map((n,k)=>n-a[k])),u=unit(cross(Math.abs(t[2])>.97?[0,1,0]:[0,0,1],t)),v=unit(cross(t,u));return Array.from({length:8},(_,j)=>p.map((n,k)=>n+rr*(u[k]*ROOT_SECTION[j][0]+v[k]*ROOT_SECTION[j][1])));});for(let i=0;i<rings.length-1;i++)for(let j=0;j<8;j++){const k=(j+1)%8,a=rings[i][j],b=rings[i][k],c=rings[i+1][k],d=rings[i+1][j];m.face(id,[a,b,c],ramp);m.face(id,[a,c,d],ramp);}return m.finish();}
export function paintRootMesh(c,faces,x=50,y=57.5){c.save();c.translate(x,y);for(const f of faces){c.beginPath();f.points.forEach((p,i)=>{const q=rootProject(p);i?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y);});c.closePath();c.fillStyle=f.fill;c.fill();c.strokeStyle=f.fill;c.lineWidth=.28;c.stroke();}c.restore();}
export function elasticPose(start,end,tension=0,beat=0,soft=false){const q=Math.max(0,Math.min(1,tension)),dx=end[0]-start[0],dy=end[1]-start[1],d=Math.hypot(dx,dy)||1,slack=(1-q)*12;return{radius:3.4/Math.sqrt(1+q*2.2),points:Array.from({length:25},(_,i)=>{const t=i/24,w=Math.sin(t*Math.PI*3)*slack,wiggle=soft?0:Math.sin(t*8-beat*6)*Math.sin(Math.PI*t)*(1-q)*1.3;return[start[0]+dx*t-dy/d*w,start[1]+dy*t+dx/d*w,start[2]+(end[2]-start[2])*t+Math.sin(t*Math.PI)*(slack*.5+wiggle)];})};}
